package com.dronefleet.service;import com.dronefleet.domain.*;import java.util.*;public final class AnalyticsService{private final FleetService fleet;private final DeliveryService delivery;public AnalyticsService(FleetService f,DeliveryService d){fleet=f;delivery=d;}public long droneCount(){return fleet.all().size();}public long activeDrones(){return fleet.all().stream().filter(x->x.status()==DroneStatus.BUSY).count();}public long chargingDrones(){return fleet.all().stream().filter(x->x.status()==DroneStatus.CHARGING).count();}public long lowBattery(){return fleet.all().stream().filter(x->x.status()==DroneStatus.LOW_BATTERY).count();}public long completed(){return delivery.all().stream().filter(x->x.status()==DeliveryStatus.COMPLETED).count();}public long activeDeliveries(){return delivery.all().stream().filter(x->x.status()==DeliveryStatus.ASSIGNED||x.status()==DeliveryStatus.IN_TRANSIT).count();}public double revenue(){return delivery.all().stream().filter(x->x.status()==DeliveryStatus.COMPLETED).mapToDouble(Delivery::charge).sum();}public Map<String,Long> deliveriesByType(){Map<String,Long> m=new TreeMap<>();for(Delivery x:delivery.all())if(x.droneId()!=null)fleet.all().stream().filter(d->d.id()==x.droneId()).findFirst().ifPresent(d->m.merge(d.type(),1L,Long::sum));return m;}}
